#!/usr/bin/env node
/**
 * fix-term-forms-case.mjs — lowercase the VALUE column of term-forms.txt.
 *
 * render-corpus emits a term pin verbatim for a lowercase source word
 * (`${tr} (${w})`, render-corpus.mjs L169) and capitalises only when the source
 * word is itself capitalised AND opted into term-caps.txt. So a capitalised pin
 * value shouts in the middle of a sentence: "And I Amar (said) in my lab".
 *
 * Every pin generated by build-term-candidates before this fix was capitalised.
 * This rewrites them in place. Comments, blank lines and the word column are
 * untouched, and the original is kept as term-forms.txt.bak.
 *
 * DRY RUN BY DEFAULT — prints what would change and writes nothing.
 *
 * USAGE
 *   node fix-term-forms-case.mjs              # preview
 *   node fix-term-forms-case.mjs --apply      # write (keeps a .bak)
 *   node fix-term-forms-case.mjs --file other-file.txt --apply
 */

import { readFileSync, writeFileSync, existsSync, copyFileSync } from 'fs';

const argv = process.argv.slice(2);
const arg = (n, d = null) => {
    const i = argv.indexOf('--' + n);
    return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[i + 1] : d;
};
const FILE  = arg('file', './term-forms.txt');
const APPLY = argv.includes('--apply');

if (!existsSync(FILE)) { console.error(`${FILE} not found`); process.exit(1); }

const lines = readFileSync(FILE, 'utf8').split(/\r?\n/);
const out = [];
const changed = [];

for (const line of lines) {
    const t = line.trim();
    // preserve comments, blanks and anything that is not a two-column pin
    if (!t || t.startsWith('#')) { out.push(line); continue; }
    // <word> <whitespace> <value> [trailing comment]
    const m = /^(\s*)([^\s#]+)(\s+)([^\s#]+)(\s*(?:#.*)?)$/.exec(line);
    if (!m) { out.push(line); continue; }
    const [, lead, word, gap, value, tail] = m;
    const lower = value.toLowerCase();
    if (lower === value) { out.push(line); continue; }
    changed.push({ word, from: value, to: lower });
    out.push(`${lead}${word}${gap}${lower}${tail}`);
}

console.log(`${FILE}: ${lines.length} lines, ${changed.length} pin value(s) to lowercase`);
for (const c of changed.slice(0, 60))
    console.log(`  ${c.word.padEnd(18)} ${c.from.padEnd(18)} -> ${c.to}`);
if (changed.length > 60) console.log(`  … and ${changed.length - 60} more`);

if (!changed.length) { console.log('nothing to do.'); process.exit(0); }

if (!APPLY) {
    console.log('\nDRY RUN — nothing written. Re-run with --apply to write (a .bak is kept).');
} else {
    copyFileSync(FILE, FILE + '.bak');
    writeFileSync(FILE, out.join('\n'));
    console.log(`\nwritten. original saved as ${FILE}.bak`);
    console.log('now: node render-all.mjs --surface');
}
